/* Dependency-aware, uncompressed ZIP backup; all work stays in the browser. */
(function(g){
 const enc=new TextEncoder();
 function dependencies(backup){if(!backup.complete||backup.patches.length!==50)throw Error('Complete 50-patch backup required');const used=new Map();for(const p of backup.patches){const b=p.rawHex.split(' ').map(x=>parseInt(x,16));if(b.length!==122)throw Error('Invalid patch data');for(let i=0;i<6;i++){const n=i*18,id=((b[n]|b[n+1]<<8|b[n+2]<<16|b[n+3]<<24)>>>1)&0xfffffff;if(!id)continue;const key=id.toString(16).padStart(8,'0');if(!used.has(key))used.set(key,[]);used.get(key).push({patch:p.slot,effectSlot:i+1,enabled:!!(b[n]&1)});}}return used;}
 function crc32(b){let c=0xffffffff;for(const x of b){c^=x;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
 function zip(files){const parts=[],central=[];let offset=0,centralLength=0;for(const [name,data] of files){const n=enc.encode(name),c=crc32(data),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,c,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,n.length,true);h.set(n,30);parts.push(h,data);const d=new Uint8Array(46+n.length),w=new DataView(d.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint32(16,c,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,n.length,true);w.setUint32(42,offset,true);d.set(n,46);central.push(d);centralLength+=d.length;offset+=h.length+data.length;}const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,centralLength,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
 g.BackupBundle={dependencies,zip};if(typeof document==='undefined'||g.backupBundleUI)return;g.backupBundleUI=true;
 const button=document.createElement('button'),status=document.createElement('p');button.textContent='Download patches + effects ZIP';el('staging').append(button,status);
 button.onclick=async()=>{if(g.backupBundleBusy)return;g.backupBundleBusy=true;button.disabled=true;try{const backup=patchBackup.last;if(!backup)throw Error('Sync from pedal first');const deps=dependencies(backup);status.textContent='Collecting effect binaries…';const catalog=await effectStore.catalog();if(!catalog.length)throw Error('No effects in this browser yet. Import your FX archive first.');const index={effects:catalog.reduce((m,e)=>((m[e.effectId]??=[]).push(e),m),{})},files=[['patches.json',enc.encode(JSON.stringify(backup,null,2))]],manifest={format:'stompshare-bundle',version:1,createdAt:new Date().toISOString(),patchCount:50,restoreTested:false,installedVersionsVerified:false,effects:[],missingEffectIds:[]};
 for(const [id,usedBy] of deps){const variants=index.effects[id];if(!variants?.length){manifest.missingEffectIds.push(id);continue;}for(const item of variants){const b=await effectStore.binary(item),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');if(item.sha256&&hash!==item.sha256)throw Error('Checksum mismatch: '+item.filename);const path='effects/'+(item.path?item.path.split('/').at(-1):item.effectId+'-'+item.filename);files.push([path,b]);manifest.effects.push({...item,path,usedBy});}}
 manifest.allReferencedEffectIdsBundled=manifest.missingEffectIds.length===0;files.push(['manifest.json',enc.encode(JSON.stringify(manifest,null,2))]);files.push(['README.txt',enc.encode('Saved patches plus matching local effect binaries. Exact installed binary versions are not verified. Restore is not implemented/tested. Patch effect IDs include bypassed slots. See manifest.json for provenance, hashes and any missing dependencies. This is not a firmware/global-settings backup.\n')]);const blob=zip(files),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='ms100bt-bundle-'+manifest.createdAt.replaceAll(':','-')+(manifest.allReferencedEffectIdsBundled?'':'-INCOMPLETE')+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=`Packaged 50 patches and ${manifest.effects.length} binaries. Missing effect IDs: ${manifest.missingEffectIds.length}. Installed versions and restore remain unverified.`;
 }catch(e){status.textContent=e.message;}finally{g.backupBundleBusy=false;button.disabled=false;}};
})(globalThis);
